"""
Application configuration settings.
"""
from typing import Optional, Any, Dict, List, Callable
from pydantic_settings import BaseSettings
from functools import lru_cache
import os
from pydantic import ValidationError, field_validator, Field
from enum import Enum
from dataclasses import dataclass, field


class FailureStrategy(Enum):
    """失败策略枚举"""
    TERMINATE = "terminate"      # 终止程序
    USE_DEFAULT = "use_default"  # 使用默认值
    ROLLBACK = "rollback"        # 回滚配置


@dataclass
class ValidationResult:
    """验证结果"""
    source: str
    is_valid: bool
    errors: List[str] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)


@dataclass
class ValidationReport:
    """验证报告"""
    total_sources: int = 0
    valid_sources: int = 0
    invalid_sources: int = 0
    results: List[ValidationResult] = field(default_factory=list)


class EnvConfigSource:
    """环境变量配置源验证器"""

    def __init__(self, prefix: str = "APP_", required_vars: Optional[List[str]] = None,
                 var_types: Optional[Dict[str, type]] = None,
                 var_constraints: Optional[Dict[str, Callable]] = None):
        """
        初始化环境变量配置源验证器

        Args:
            prefix: 环境变量前缀过滤
            required_vars: 必需的环境变量列表
            var_types: 环境变量类型映射 {"VAR_NAME": type}
            var_constraints: 环境变量约束函数 {"VAR_NAME": callable}
        """
        self.prefix = prefix
        self.required_vars = required_vars or []
        self.var_types = var_types or {}
        self.var_constraints = var_constraints or {}
        self._env_cache: Dict[str, str] = {}

    def load_env_vars(self) -> Dict[str, str]:
        """加载所有以指定前缀开头的环境变量"""
        self._env_cache = {
            key: value for key, value in os.environ.items()
            if key.startswith(self.prefix)
        }
        return self._env_cache

    def get_env_var(self, name: str, default: Optional[str] = None) -> Optional[str]:
        """
        获取环境变量值

        Args:
            name: 环境变量名称（不含前缀）
            default: 默认值

        Returns:
            环境变量值或默认值
        """
        full_name = f"{self.prefix}{name}"
        return os.environ.get(full_name, default)

    def set_env_var(self, name: str, value: str) -> None:
        """
        设置环境变量（仅影响缓存，不影响实际进程环境）

        Args:
            name: 环境变量名称（不含前缀）
            value: 环境变量值
        """
        full_name = f"{self.prefix}{name}"
        self._env_cache[full_name] = value

    def validate(self) -> ValidationResult:
        """
        验证环境变量配置

        Returns:
            ValidationResult: 验证结果
        """
        errors: List[str] = []
        warnings: List[str] = []

        # 加载环境变量
        self.load_env_vars()

        # 检查必需的环境变量
        for var_name in self.required_vars:
            full_name = f"{self.prefix}{var_name}"
            if full_name not in self._env_cache:
                errors.append(f"Required environment variable missing: {full_name}")

        # 验证类型
        for var_name, expected_type in self.var_types.items():
            full_name = f"{self.prefix}{var_name}"
            if full_name in self._env_cache:
                value = self._env_cache[full_name]
                try:
                    if expected_type == bool:
                        if value.lower() not in ('true', 'false', '1', '0', 'yes', 'no'):
                            errors.append(
                                f"Invalid boolean value for {full_name}: {value}"
                            )
                    elif expected_type == int:
                        int(value)
                    elif expected_type == float:
                        float(value)
                except (ValueError, TypeError) as e:
                    errors.append(
                        f"Invalid type for {full_name}: expected {expected_type.__name__}, got '{value}'"
                    )

        # 验证约束
        for var_name, constraint_func in self.var_constraints.items():
            full_name = f"{self.prefix}{var_name}"
            if full_name in self._env_cache:
                value = self._env_cache[full_name]
                try:
                    if not constraint_func(value):
                        warnings.append(
                            f"Value for {full_name} did not pass constraint check: {value}"
                        )
                except Exception as e:
                    errors.append(
                        f"Constraint validation failed for {full_name}: {str(e)}"
                    )

        is_valid = len(errors) == 0

        return ValidationResult(
            source=f"env_config_source({self.prefix})",
            is_valid=is_valid,
            errors=errors,
            warnings=warnings
        )

    def validate_value(self, name: str, value: Any) -> bool:
        """
        验证单个环境变量值

        Args:
            name: 环境变量名称（不含前缀）
            value: 要验证的值

        Returns:
            bool: 验证是否通过
        """
        full_name = f"{self.prefix}{name}"

        # 类型检查
        if name in self.var_types:
            expected_type = self.var_types[name]
            try:
                if expected_type == bool:
                    if isinstance(value, bool):
                        return True
                    if isinstance(value, str) and value.lower() in ('true', 'false', '1', '0', 'yes', 'no'):
                        return True
                    return False
                elif expected_type in (int, float, str):
                    expected_type(value)
                    return True
                else:
                    expected_type(value)
                    return True
            except (ValueError, TypeError):
                return False

        # 约束检查
        if name in self.var_constraints:
            try:
                return self.var_constraints[name](value)
            except Exception:
                return False

        return True


class ConfigValidationRunner:
    """配置验证运行器"""

    def __init__(self):
        self._failure_strategy: FailureStrategy = FailureStrategy.TERMINATE
        self._validation_report: ValidationReport = ValidationReport()
        self._config_sources: Dict[str, Any] = {}

    def set_failure_strategy(self, strategy: str) -> None:
        """
        设置失败策略

        Args:
            strategy: 策略名称，可选值：terminate/use_default/rollback

        Raises:
            ValueError: 当策略名称无效时
        """
        try:
            self._failure_strategy = FailureStrategy(strategy)
        except ValueError:
            raise ValueError(
                f"Invalid failure strategy: {strategy}. "
                f"Must be one of {[s.value for s in FailureStrategy]}"
            )

    def get_failure_strategy(self) -> FailureStrategy:
        """获取当前失败策略"""
        return self._failure_strategy

    def register_config_source(self, name: str, config: Any) -> None:
        """
        注册配置源

        Args:
            name: 配置源名称
            config: 配置对象（通常是 Pydantic Settings 实例）
        """
        self._config_sources[name] = config

    def validate_source(self, source_name: str) -> ValidationResult:
        """
        验证单个配置源

        Args:
            source_name: 配置源名称

        Returns:
            ValidationResult: 验证结果
        """
        if source_name not in self._config_sources:
            return ValidationResult(
                source=source_name,
                is_valid=False,
                errors=[f"Config source not found: {source_name}"]
            )

        config = self._config_sources[source_name]

        # 如果是 EnvConfigSource，使用其验证方法
        if isinstance(config, EnvConfigSource):
            return config.validate()

        # 如果是 Pydantic Settings 实例
        if isinstance(config, BaseSettings):
            try:
                # 触发所有字段的验证
                config.model_dump()
                return ValidationResult(
                    source=source_name,
                    is_valid=True
                )
            except ValidationError as e:
                errors = [f"{err['loc']}: {err['msg']}" for err in e.errors()]
                return ValidationResult(
                    source=source_name,
                    is_valid=False,
                    errors=errors
                )

        # 通用验证
        return ValidationResult(
            source=source_name,
            is_valid=True
        )

    def run_validation(self) -> ValidationReport:
        """
        运行所有配置源的验证

        Returns:
            ValidationReport: 验证报告
        """
        report = ValidationReport()
        report.total_sources = len(self._config_sources)

        for name, config in self._config_sources.items():
            result = self.validate_source(name)
            report.results.append(result)

            if result.is_valid:
                report.valid_sources += 1
            else:
                report.invalid_sources += 1

        self._validation_report = report
        return report

    def handle_validation_failure(self, report: ValidationReport) -> None:
        """
        处理验证失败

        Args:
            report: 验证报告

        Raises:
            ValueError: 当策略为 TERMINATE 且验证失败时
        """
        if report.invalid_sources == 0:
            return

        if self._failure_strategy == FailureStrategy.TERMINATE:
            error_messages = []
            for result in report.results:
                if not result.is_valid:
                    error_messages.append(f"{result.source}: {', '.join(result.errors)}")
            raise ValueError(
                f"Configuration validation failed: {'; '.join(error_messages)}"
            )
        elif self._failure_strategy == FailureStrategy.USE_DEFAULT:
            # 使用默认配置的逻辑可以在这里实现
            pass
        elif self._failure_strategy == FailureStrategy.ROLLBACK:
            # 回滚配置的逻辑可以在这里实现
            pass

    def get_validation_report(self) -> ValidationReport:
        """获取验证报告"""
        return self._validation_report

